package com.sobrenaturaldirector.decision.utility;
import java.util.*;
public final class UtilityScoreBreakdown { private final double finalScore; private final List<FactorResult> factors; private final Map<String,Double> penalties; public UtilityScoreBreakdown(double score,List<FactorResult> factors,Map<String,Double> penalties){if(Double.isNaN(score)||Double.isInfinite(score))throw new IllegalArgumentException("non-finite score");finalScore=score;this.factors=Collections.unmodifiableList(new ArrayList<FactorResult>(factors));this.penalties=Collections.unmodifiableMap(new LinkedHashMap<String,Double>(penalties));} public double getFinalScore(){return finalScore;} public List<FactorResult> getFactors(){return factors;} public Map<String,Double> getPenalties(){return penalties;} }
